 /// text=3, button=4, spacer=8). Returns 1 on success, 0 on bad component.
 #[no_mangle]
 pub unsafe extern "C" fn pathland_native_create_node(
     host: HostHandle,
     id: u32,
     component: u32,
 ) -> u8 {
     let Some(component) = component_from_id(component) else {
